import math

def check_condition(n):
    if n < 0:
        return False

    divisor = 2 * n - 1

    # Handle n=0 case where divisor = -1
    if n == 0:
        # 3*((2)! + 1) / -1 = 9 / -1 = -9. Integer.
        return True

    if divisor == 0:
        # Should not happen for nonnegative n
        return False

    try:
        numerator = 3 * (math.factorial(n + 2) + 1)
        if numerator % divisor == 0:
            return True
        else:
            return False
    except OverflowError:
        # For very large n, factorials overflow standard floats/ints. 
        # We check based on modular arithmetic if possible, but for brute force up to 10, this is fine.
        return None

# Test n = 0 to 10
solutions = []
for n in range(11):
    if check_condition(n):
        solutions.append(n)

print(f"Solutions found for n=0 to 10: {solutions}")

import math

def check_expression(n):
    # Handle n=0 case explicitly as 2n-1 = -1
    if n == 0:
        # This was checked in Round 1, E(0) = 3((2)! + 1) / -1 = 9 / -1 = -9 (Integer)
        return -9

    # For n >= 1, 2n-1 >= 1
    denominator = 2 * n - 1
    try:
        numerator = 3 * (math.factorial(n + 2) + 1)
    except OverflowError:
        # Should not happen for n up to 20, but good practice
        return float('inf') 

    if denominator == 0:
        # Should not happen for nonnegative integers n
        return None

    result = numerator / denominator

    # Check if the result is an integer
    if result == int(result):
        return int(result)
    else:
        return f"Not an integer (~{result:.2f})"

results = {}
for n in range(11, 21):
    results[n] = check_expression(n)

print("Results for n=11 to n=20:")
for n, result in results.items():
    print(f"n={n}: {result}")

